// Generates every file derived from a single source of truth:
//   product.json                 -> src/core/product.ts, src-tauri/tauri.conf.json
// Runs on `npm install` (postinstall) and before dev/build/check, so generated files never drift.
// Generated files are git-ignored; edit the sources instead.
// (tokens.css is hand-authored since M1.5 — DESIGN.md §19.)
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = async (p) => JSON.parse(await readFile(join(root, p), "utf8"));
const banner = "GENERATED by scripts/gen.mjs — do not edit.";

/** Only write when content changed, so watchers don't loop. */
async function writeIfChanged(rel, content) {
  const path = join(root, rel);
  const old = await readFile(path, "utf8").catch(() => "");
  if (old !== content) await writeFile(path, content);
}

// A release that adds a package (pele and KaTeX in m6.73) fails to build until `npm install`
// runs: before dev / build / check, install what package.json lists but node_modules lacks
// (D173). Not during npm's own postinstall (that is the install).
if (process.env.npm_lifecycle_event !== "postinstall") {
  const pkg = await read("package.json");
  // Dev packages aren't expected where they're left out on purpose (npm --omit=dev, production).
  const omitDev =
    process.env.NODE_ENV === "production" || /\bdev\b/.test(process.env.npm_config_omit ?? "");
  const wanted = { ...pkg.dependencies, ...(omitDev ? {} : pkg.devDependencies) };
  const missing = Object.keys(wanted).filter(
    (name) => !existsSync(join(root, "node_modules", name, "package.json")),
  );
  if (missing.length) {
    console.log(`gen: installing new packages (${missing.join(", ")})…`);
    // Through the shell: npm is npm.cmd on Windows.
    const result = spawnSync("npm install", { cwd: root, stdio: "inherit", shell: true });
    if (result.status !== 0) {
      console.error("gen: npm install failed; run it yourself, then try again.");
      process.exit(result.status ?? 1);
    }
  }
}

const product = await read("product.json");
// Other folder names a project may already have for the IDE's workspace files (D177): the first
// that exists is used instead of workspaceFolderName (e.g. ".vscode").
const aliases = product.workspaceFolderAliases ?? [];
if (
  !Array.isArray(aliases) ||
  aliases.some((a) => typeof a !== "string" || !/^\.?[A-Za-z0-9][\w.-]*$/.test(a))
)
  throw new Error('product.json: "workspaceFolderAliases" must be a list of folder names');
const required = [
  "nameShort",
  "nameLong",
  "identifier",
  "dataFolderName",
  "workspaceFolderName",
  "urlScheme",
  "extensionApiGlobal",
];
for (const key of required) {
  if (typeof product[key] !== "string" || product[key] === "") {
    throw new Error(`product.json: "${key}" must be a non-empty string`);
  }
}
// Optional: empty means "not available yet" (accountsUrl: the IDE account's server, D140).
// extensionsRepo: the git repository of official extensions (D185). issuesUrl: where Help →
// Report a problem opens a new issue (a GitHub repository's ".../issues", D204).
// serverDataFolderName: the remote server's folder in a remote machine's home (D252, read by Rust).
const optional = ["accountsUrl", "extensionsRepo", "issuesUrl", "serverDataFolderName"];
if (
  product.updates !== undefined &&
  (typeof product.updates !== "object" ||
    ["endpoint", "betaEndpoint", "pubkey"].some(
      (k) => product.updates[k] !== undefined && typeof product.updates[k] !== "string",
    ))
)
  throw new Error(
    'product.json: "updates" must be { "endpoint": string, "betaEndpoint": string, "pubkey": string }',
  );
for (const key of optional) {
  if (product[key] !== undefined && typeof product[key] !== "string")
    throw new Error(`product.json: "${key}" must be a string`);
}
const pkg = await read("package.json");

// --- src/core/product.ts ---------------------------------------------------
await writeIfChanged(
  "src/core/product.ts",
  `// ${banner}\n// Source: product.json. Never hard-code product names anywhere else.\n` +
    `export interface ProductConfig {\n${required.map((k) => `  readonly ${k}: string;`).join("\n")}\n${optional.map((k) => `  readonly ${k}: string;`).join("\n")}\n  readonly workspaceFolderAliases: readonly string[];\n  readonly version: string;\n}\n\n` +
    `export const product: ProductConfig = ${JSON.stringify({ ...pick(product, required), ...Object.fromEntries(optional.map((k) => [k, product[k] ?? ""])), workspaceFolderAliases: aliases, version: pkg.version }, null, 2)};\n`,
);

// --- src-tauri/tauri.conf.json ---------------------------------------------
const base = await read("src-tauri/tauri.base.json");
const conf = structuredClone(base);
// (tauri.conf.json is strict JSON with no comment field; it is git-ignored and documented in README.)
conf.productName = product.nameLong;
// The program's file name (Jonna.exe, not the Cargo package's ide.exe): what Windows shows in the
// UAC prompt, Task Manager, the Start menu shortcut's target and the installer.
conf.mainBinaryName = product.nameShort;
conf.version = pkg.version;
conf.identifier = product.identifier;
for (const win of conf.app.windows) win.title = product.nameLong;
// Updates (D192): only a build with both an endpoint and the updater's public key gets the
// updater (the release workflow passes them; a build without them never checks).
const updates = product.updates ?? {};
const endpoint = process.env.IDE_UPDATE_ENDPOINT || updates.endpoint || "";
const pubkey = process.env.IDE_UPDATE_PUBKEY || updates.pubkey || "";
if (endpoint && pubkey) {
  conf.plugins = {
    ...conf.plugins,
    updater: { pubkey, endpoints: [endpoint], windows: { installMode: "passive" } },
  };
  // Signed update files need the private key; a build without it (the release workflow says
  // with UPDATE_SIGNING) still checks for updates but makes none itself.
  if (process.env.UPDATE_SIGNING !== "false") conf.bundle.createUpdaterArtifacts = true;
}
// Windows code signing (D192): the release workflow sets the command (Azure Trusted Signing or
// any signtool-compatible tool; %1 is the file). Unsigned without it.
if (process.env.IDE_WINDOWS_SIGN_COMMAND)
  conf.bundle.windows = {
    ...conf.bundle.windows,
    signCommand: process.env.IDE_WINDOWS_SIGN_COMMAND,
  };
// A newer ConPTY for Windows 10 (m7.12): conpty.dll and OpenConsole.exe from Microsoft's
// Microsoft.Windows.Console.ConPTY package (MIT), put in src-tauri/conpty/<arch>/ by
// scripts/fetch-conpty.mjs, are installed next to the program, where the terminal loads them
// (src-tauri/src/pty/conpty.rs). Without them nothing is added and the system's ConPTY is used.
const conptyArch = process.env.IDE_CONPTY_ARCH || process.arch;
const conptyDir = `conpty/${conptyArch}`;
if (
  process.platform === "win32" &&
  ["conpty.dll", "OpenConsole.exe"].every((f) => existsSync(join(root, "src-tauri", conptyDir, f)))
)
  conf.bundle.resources = {
    ...conf.bundle.resources,
    [`${conptyDir}/conpty.dll`]: "conpty.dll",
    [`${conptyDir}/OpenConsole.exe`]: "OpenConsole.exe",
  };
// The remote development server (D252): the Linux builds scripts/build-server.mjs made, installed
// with the app (a remote window uploads the one for the remote's machine). Only those built.
for (const target of ["x86_64-unknown-linux-musl", "aarch64-unknown-linux-musl"]) {
  const rel = `resources/server/${target}/ide-server`;
  if (existsSync(join(root, "src-tauri", rel)))
    conf.bundle.resources = { ...conf.bundle.resources, [rel]: `server/${target}/ide-server` };
}
await writeIfChanged("src-tauri/tauri.conf.json", `${JSON.stringify(conf, null, 2)}\n`);

// --- src/extensions/agent/brandLogos.ts (D167) -------------------------------
// Official logos the owner adds to src/assets/brands/<brand>.svg (from each company's brand kit,
// following its guidelines) replace the letter badges on the AI models page. Never drawn here.
// SVGs with scripts or event handlers are skipped; the rest load as <img> (no script runs there).
const brandsDir = join(root, "src/assets/brands");
const logos = {};
for (const name of (await readdir(brandsDir).catch(() => [])).sort()) {
  if (!/^[a-z0-9-]+\.svg$/.test(name)) continue;
  const svg = await readFile(join(brandsDir, name), "utf8");
  if (/<script|\son[a-z]+\s*=|javascript:|<foreignObject/i.test(svg)) {
    console.warn(`gen: skipped ${name} (scripts or event handlers)`);
    continue;
  }
  // One-color logos (no colors of their own) are drawn in white on the brand's color (a CSS
  // mask); colored ones are shown as they are.
  const mono = !/(fill|stop-color|stroke)="(#|rgb|url)/i.test(svg);
  logos[name.slice(0, -4)] = {
    src: `data:image/svg+xml,${encodeURIComponent(svg.trim())}`,
    mono,
  };
}
await writeIfChanged(
  "src/extensions/agent/brandLogos.ts",
  `// ${banner}\n// Source: src/assets/brands/*.svg (official logos, if added; see its README).\n` +
    `export const BRAND_LOGOS: Readonly<Record<string, { src: string; mono: boolean }>> = ${JSON.stringify(logos, null, 2)};\n`,
);

function pick(obj, keys) {
  return Object.fromEntries(keys.map((k) => [k, obj[k]]));
}
